<script>
 import {saveFileAs,descriptor,useBrowserDownloads} from '../local-downloads.js';
 import {onDestroy} from 'svelte';import {createExportPreview} from '../export-preview';
 import {FolderOpen,Download,Check,AlertCircle,Copy} from 'lucide-svelte';import {studio,scope,asset,run,save,refresh,notify,referencePreview,current,liveAssets,importImages,editFor} from '../studio.svelte';import {api,stored,persist,rgb,hex,bytes,isTeam} from '../api';import ScopePicker from './ScopePicker.svelte';
 const initialPreset=stored('export',{format:'webp',width:1000,height:1000,fit:'pad',quality:92,maxBytes:800000,outputDir:'',background:[255,255,255]});if(isTeam&&!initialPreset.outputDir)initialPreset.outputDir='浏览器另存为（下载 / 桌面）';let preset=$state(initialPreset);let limit=$state(initialPreset.maxBytes>0),report=$state(null),attempted=$state(0),cancelled=$state(0);
 let leadId=$derived(scope().includes(studio.aid)?studio.aid:scope()[0]);let lead=$derived(current()?.assets.find(a=>a.id===leadId));
 let errors=$derived([!Number.isInteger(preset.width)||preset.width<1||preset.width>16000?'宽度必须为 1 至 16000 像素。':'',!Number.isInteger(preset.height)||preset.height<1||preset.height>16000?'高度必须为 1 至 16000 像素。':'',preset.width*preset.height>120000000?'图片总像素不能超过 1.2 亿。':'',limit&&(!Number.isFinite(preset.maxBytes)||preset.maxBytes<1000)?'文件大小上限至少为 1 KB。':'',preset.format!=='png'&&(!Number.isInteger(preset.quality)||preset.quality<1||preset.quality>100)?'质量必须为 1 至 100。':''].filter(Boolean));
 let encoded=$state({loading:false,result:null,error:''}),showBefore=$state(false);
 const previewController=createExportPreview({request:args=>api('export_preview',args),onChange:value=>encoded=value});
 onDestroy(()=>previewController.dispose());
 $effect(()=>{
  studio.dataRoot;lead?.generatedBase;
  const ready=studio.mode==='export'&&!studio.busy&&lead&&!errors.length;
  const request=ready?{projectId:studio.pid,assetId:leadId,edit:leadId===studio.aid?studio.draft:editFor(lead),preset:{...preset,outputDir:'',quality:preset.format==='png'?100:preset.quality,maxBytes:limit?preset.maxBytes:0}}:null;
  previewController.set(request?JSON.parse(JSON.stringify(request)):null);
 });
 async function choose(){const path=await api('pick_output');if(path)preset.outputDir=path;}
 async function exportNow(){if(errors.length||!preset.outputDir.trim())return;await run("正在导出",async()=>{const ids=[...scope()];attempted=ids.length;report=null;await save(ids);const settings={...preset,quality:preset.format==='png'?100:preset.quality,maxBytes:limit?preset.maxBytes:0};persist('export',settings);report=await api('export_run',{projectId:studio.pid,ids,preset:settings});cancelled=attempted-report.length;await refresh();const succeeded=report.filter(i=>i.status==='ok').length;notify(`已导出 ${succeeded} 张${report.length-succeeded?` · ${report.length-succeeded} 张需要检查`:''}${cancelled?` · ${cancelled} 张已取消`:''}`);});}
 const status=s=>s==='ok'?"已导出":s==='EXPORT_TARGET_UNREACHABLE'?"未达到大小要求":s.split(':')[0].replaceAll('_',' ').toLowerCase();
</script>
{#if !liveAssets().length}<div class="workflow-panel"><div class="empty"><h2>没有可导出的图片</h2><button class="primary" onclick={()=>importImages(false)}>导入图片</button></div></div>{:else}<div class="workflow-panel export-panel" inert={!!studio.busy}><div class="workflow-heading"><h1>导出</h1></div><ScopePicker/><div class="export-layout"><div class="export-preview"><div class="segmented" role="group" aria-label="导出效果对比"><button class:active={!showBefore} aria-pressed={!showBefore} onclick={()=>showBefore=false}>导出后</button><button class:active={showBefore} aria-pressed={showBefore} onclick={()=>showBefore=true}>导出前</button></div>{#if encoded.result}<img src={showBefore?encoded.result.beforeUrl:encoded.result.url} alt={showBefore?"调整导出设置前":"实际导出效果"}/><span>{encoded.result.width} × {encoded.result.height} · {preset.format.toUpperCase()} · {encoded.result.bytes.toLocaleString()} bytes{#if preset.format!=='png'} · Quality {encoded.result.quality}{/if}</span>{#if encoded.result.status!=='ok'}<p class="field-error" role="status">文件仍超过大小上限。请提高上限或调整导出设置。</p>{/if}{:else if encoded.loading}<p role="status">正在生成导出预览…</p>{:else if encoded.error}<p class="field-error" role="alert">{encoded.error}</p>{:else}<p class="hint">请先修正导出设置。</p>{/if}<span>{lead?.name}</span>{#if scope().length>1}<span>{scope().length} 张图片使用这些导出设置</span>{/if}</div><div class="export-form"><div class="section-row"><h3>导出后</h3><button class="text-button" type="button" onclick={()=>{preset={format:'webp',width:1000,height:1000,fit:'pad',quality:92,maxBytes:800000,outputDir:'',background:[255,255,255]};limit=true;report=null;persist('export',preset);}}>恢复默认设置</button></div><label>图片格式<select aria-label="导出格式" bind:value={preset.format}><option value="webp">WebP</option><option value="jpeg">JPEG</option><option value="png">PNG</option></select></label><div class="field-grid"><label>宽度<input type="number" aria-label="导出宽度" min="1" max="16000" step="1" bind:value={preset.width}/></label><label>高度<input type="number" aria-label="导出高度" min="1" max="16000" step="1" bind:value={preset.height}/></label></div><label>画面适配方式<select aria-label="导出适配方式" bind:value={preset.fit}><option value="pad">补边：保留完整图片</option><option value="crop">裁切：填满画面</option></select></label><label>背景颜色<input type="color" value={hex(preset.background)} onchange={e=>preset.background=rgb(e.target.value)}/></label>{#if preset.format!=='png'}<label>图片质量<input aria-label="导出质量" type="number" min="1" max="100" bind:value={preset.quality}/></label>{/if}<label class="checkbox-label"><input type="checkbox" bind:checked={limit}/>限制文件大小</label>{#if limit}<label>最大文件大小（KB）<input aria-label="最大文件大小（KB）" type="number" min="1" value={preset.maxBytes/1000} oninput={e=>preset.maxBytes=Number(e.target.value)*1000}/></label>{#if preset.format==='png'}<p class="hint">PNG 使用无损压缩。若超过大小上限，请缩小尺寸或改用 WebP。</p>{/if}{/if}<label>文件夹<div class="input-action"><input aria-label="保存文件夹" readonly={isTeam} bind:value={preset.outputDir} placeholder="请选择保存文件夹"/><button aria-label="选择保存文件夹" onclick={()=>run("正在选择文件夹",choose)}><FolderOpen size={17}/></button></div></label>{#if isTeam}<button class="text-button" onclick={async()=>preset.outputDir=await useBrowserDownloads()}>使用浏览器另存为（下载 / 桌面）</button>{/if}{#each errors as error}<p class="field-error" role="status">{error}</p>{/each}<button class="primary full" disabled={!!studio.busy||!scope().length||!!errors.length||!preset.outputDir.trim()} onclick={exportNow}><Download size={16}/>导出 {scope().length} {scope().length===1?'张图片':'张图片'}</button>{#if !preset.outputDir.trim()}<p class="hint">请先选择保存文件夹。</p>{/if}</div></div>{#if report}<div class="export-results"><h3>导出结果 · {report.filter(i=>i.status==='ok').length} / {attempted} 已导出</h3>{#if cancelled}<p class="hint">{cancelled} 张图片已取消，未开始处理。</p>{/if}{#each report as item}<div class="result-row">{#if item.path}<Check size={15}/>{:else}<AlertCircle size={15}/>{/if}<span>{item.name}<small>{item.path|| (item.status==='EXPORT_TARGET_UNREACHABLE'?"请提高文件大小上限、缩小尺寸，或改用 WebP。":item.status)}</small></span><b>{bytes(item.bytes)}</b><em>{status(item.status)}</em>{#if item.path&&isTeam}<a href={item.path} download={item.downloadName||item.name} onclick={e=>{e.preventDefault();saveFileAs(descriptor(item.path,item.downloadName||item.name)).catch(e=>studio.error=e.message);}}>另存为</a>{:else if item.path}<button aria-label={`Copy path for ${item.name}`} onclick={async()=>{try{await navigator.clipboard.writeText(item.path);notify("已复制路径");}catch{notify("请选择路径后复制");}}}><Copy size={14}/></button>{/if}</div>{/each}</div>{/if}</div>
{/if}

